using FluentValidation;
namespace FintechApp.Requests.OverdraftDetail { public class CreateOverdraftDetailRequest { public int UserID { get; set; } public int WalletID { get; set; } public decimal OverdraftOpening { get; set; } public decimal OverdraftAmount { get; set; } public decimal OverdraftClosing { get; set; } public string UserRemark { get; set; } = string.Empty; public string AdminRemark { get; set; } = string.Empty; public string Status { get; set; } = string.Empty; public decimal OpeningWalletBalance { get; set; } } public class CreateOverdraftDetailRequestValidator : AbstractValidator<CreateOverdraftDetailRequest> { public CreateOverdraftDetailRequestValidator() { RuleFor(x => x.UserID).GreaterThan(0); } } }
